use std::path::Path;
use std::time::Instant;
use serde_json::{json, Value};
use woyo::{Lookup, Read};

type Result<T, E = Box<dyn std::error::Error>> = std::result::Result<T, E>;

enum Engine {
    Reader(woyo::Reader<memmap2::Mmap>),
    Index(woyo::Mdx),
    Lazy(lazy::MdxFile),
    Stream(stream::MdictReader<stream::Mdx>),
}

#[derive(Default)]
struct Sink {
    count: u64,
    bytes: u64,
}

impl Sink {
    fn accept(&mut self, text: &str) {
        self.count += 1;
        self.bytes += std::hint::black_box(text.as_bytes()).len() as u64;
    }
}

impl Engine {
    fn open(kind: &str, path: &Path) -> Result<Self> {
        match kind {
            "woyo-reader" => {
                // Evaluation fixtures remain immutable for the child lifetime.
                let reader = unsafe { woyo::Reader::open(path)? };
                Ok(Self::Reader(reader))
            }
            "woyo-index" => {
                let reader = unsafe { woyo::Reader::open(path)? };
                Ok(Self::Index(woyo::Mdx::new(reader)?))
            }
            "woyo-cached" => {
                Ok(Self::Index(unsafe { woyo::Mdx::open(path)? }))
            }
            "lazy" => Ok(Self::Lazy(lazy::MdxFile::open(path)?)),
            "stream" => Ok(Self::Stream(stream::MdictReader::<stream::Mdx>::new(path, None, None, false)?)),
            _ => Err(format!("unknown engine {kind}").into()),
        }
    }

    fn count(&self) -> u64 {
        match self {
            Self::Reader(reader) => reader.entries().len() as u64,
            Self::Index(dictionary) => dictionary.reader().entries().len() as u64,
            Self::Lazy(dictionary) => dictionary.len(),
            Self::Stream(reader) => reader.num_entries(),
        }
    }

    fn first(&self) -> Result<String> {
        match self {
            Self::Reader(reader) => Ok(reader.text(0)?),
            Self::Index(dictionary) => Ok(dictionary.reader().text(0)?),
            Self::Lazy(dictionary) => Ok(dictionary.entries().next().ok_or("empty")??.text),
            Self::Stream(reader) => {
                let (_, value) = reader.iter_records().next().ok_or("empty")??;
                match value {
                    stream::RecordData::Content(text) => Ok(text),
                    stream::RecordData::Redirect(target) => Ok(format!("@@@LINK={target}")),
                }
            }
        }
    }

    fn scan(&self, capture: bool, compatible: bool) -> Result<(Sink, Vec<Value>)> {
        let mut sink = Sink::default();
        let mut sample = Vec::new();
        let mut consume = |key: &str, text: &str| {
            sink.accept(text);
            if capture {
                sample.push(json!({"key":key,"text":text}));
            }
        };
        match self {
            Self::Reader(reader) => Self::scan_reader(reader, compatible, &mut consume)?,
            Self::Index(dictionary) => Self::scan_reader(dictionary.reader(), compatible, &mut consume)?,
            Self::Lazy(dictionary) => {
                for entry in dictionary.entries() {
                    let entry = entry?;
                    consume(&entry.key, &entry.text);
                }
            }
            Self::Stream(reader) => {
                for entry in reader.iter_records() {
                    let (key, entry) = entry?;
                    match entry {
                        stream::RecordData::Content(text) => consume(&key, &text),
                        stream::RecordData::Redirect(target) => consume(&key, &format!("@@@LINK={target}")),
                    }
                }
            }
        }
        Ok((sink, sample))
    }

    fn scan_reader<R: Read, F: FnMut(&str, &str)>(reader: &R, compatible: bool, mut consume: F) -> Result<()> {
        if compatible {
            for (id, entry) in reader.entries().iter().enumerate() {
                let text = reader.text(id)?;
                consume(&entry.headword, &text);
            }
        } else {
            for record in reader.records() {
                let (entry, bytes) = record?;
                let text = reader.metadata().encoding.decode(bytes.as_ref())?;
                consume(&entry.headword, text.trim_end_matches('\0').trim_end());
            }
        }
        Ok(())
    }

    fn lookup(&self, query: &str) -> Result<String> {
        match self {
            Self::Index(dictionary) => dictionary.lookup(query)?.into_iter().next().ok_or_else(|| format!("not found {query}").into()),
            Self::Lazy(dictionary) => dictionary.lookup(query)?.map(|entry| entry.text).ok_or_else(|| format!("not found {query}").into()),
            _ => Err("no native indexed lookup API".into()),
        }
    }
}

struct Bench;

impl Bench {
    fn memory() -> Value {
        let status = std::fs::read_to_string("/proc/self/status").unwrap_or_default();
        let mut memory = serde_json::Map::new();
        for line in status.lines() {
            let mut fields = line.split_whitespace();
            let Some(key) = fields.next() else { continue; };
            if ["VmRSS:", "VmHWM:"].contains(&key) {
                if let Some(value) = fields.next().and_then(|value| value.parse::<u64>().ok()) {
                    memory.insert(key.trim_end_matches(':').to_owned(), json!(value));
                }
            }
        }
        Value::Object(memory)
    }

    fn run(kind: &str, mode: &str, path: &Path) -> Result<Value> {
        let before = Self::memory();
        let start = Instant::now();
        let dictionary = Engine::open(kind, path)?;
        let open_ms = start.elapsed().as_secs_f64() * 1000.0;
        let after_open = Self::memory();
        let count = dictionary.count();
        let start = Instant::now();
        let first = if mode == "lookup" {
            dictionary.lookup(&format!("word{:08}", count / 2))?
        } else {
            dictionary.first()?
        };
        let first_ms = start.elapsed().as_secs_f64() * 1000.0;
        std::hint::black_box(&first);
        let mut result = json!({"engine":kind,"mode":mode,"path":path,"count":count,"open_ms":open_ms,"first_ms":first_ms,"before_kib":before,"open_kib":after_open});
        match mode {
            "open" => {},
            "scan" | "scan-compat" | "probe" => {
                let start = Instant::now();
                let (sink, sample) = dictionary.scan(mode == "probe", mode == "scan-compat")?;
                result["scan_ms"] = json!(start.elapsed().as_secs_f64() * 1000.0);
                result["scanned"] = json!(sink.count);
                result["bytes"] = json!(sink.bytes);
                if mode == "probe" {
                    result["records"] = json!(sample);
                }
            }
            "lookup" => {
                for (name, repeat) in [("repeat", true), ("random", false)] {
                    let mut queries = Vec::with_capacity(1000);
                    let mut state = 0x82a2b175229d6a5b_u64;
                    for _ in 0..1000 {
                        state = state.wrapping_mul(6364136223846793005).wrapping_add(1);
                        let id = if repeat { count / 2 } else { state % count };
                        queries.push(format!("word{id:08}"));
                    }
                    let mut durations = Vec::with_capacity(queries.len());
                    let mut bytes = 0;
                    for query in queries {
                        let start = Instant::now();
                        let text = dictionary.lookup(&query)?;
                        durations.push(start.elapsed().as_nanos() as u64);
                        if !text.starts_with(&query) {
                            return Err(format!("incorrect lookup: {query}: {text}").into());
                        }
                        bytes += std::hint::black_box(text.len());
                    }
                    durations.sort_unstable();
                    result[name] = json!({"p50_us":durations[durations.len()/2] as f64/1000.0,"p95_us":durations[durations.len()*95/100] as f64/1000.0,"mean_us":durations.iter().sum::<u64>() as f64/durations.len() as f64/1000.0,"bytes":bytes,"queries":durations.len()});
                }
            }
            _ => return Err(format!("unknown mode {mode}").into()),
        }
        result["end_kib"] = Self::memory();
        let cache = match &dictionary {
            Engine::Reader(reader) => Some(reader.cache_stats()),
            Engine::Index(dictionary) => Some(dictionary.reader().cache_stats()),
            _ => None,
        };
        if let Some(cache) = cache {
            result["cache"] = json!({"hits":cache.hits,"misses":cache.misses,"resident":cache.resident,"blocks":cache.blocks});
        }
        Ok(result)
    }

    fn resources(kind: &str, path: &Path) -> Result<Value> {
        let mut result = Vec::new();
        match kind {
            "woyo-reader" => {
                let reader = woyo::Reader::parse(std::fs::read(path)?, "resource")?;
                for (id, entry) in reader.entries().iter().enumerate() {
                    let bytes = reader.read(id)?;
                    result.push(json!({"key":entry.headword,"bytes":bytes.as_ref().len(),"sum":bytes.as_ref().iter().map(|byte|u64::from(*byte)).sum::<u64>()}));
                }
            }
            "lazy" => {
                let dictionary = lazy::MddFile::open(path)?;
                for entry in dictionary.entries() {
                    let entry = entry?;
                    result.push(json!({"key":entry.key,"bytes":entry.data.len(),"sum":entry.data.iter().map(|byte|u64::from(*byte)).sum::<u64>()}));
                }
            }
            "stream" => {
                let reader = stream::MdictReader::<stream::Mdd>::new(path,None,None,false)?;
                for entry in reader.iter_records() {
                    let (key, data) = entry?;
                    match data {
                        stream::RecordData::Content(bytes) => result.push(json!({"key":key,"bytes":bytes.len(),"sum":bytes.iter().map(|byte|u64::from(*byte)).sum::<u64>()})),
                        stream::RecordData::Redirect(target) => result.push(json!({"key":key,"redirect":target})),
                    }
                }
            }
            _ => return Err("unsupported resource engine".into()),
        }
        Ok(json!({"engine":kind,"path":path,"resources":result}))
    }
}

struct Audit;

impl Audit {
    fn run(root: &Path) -> Result<Value> {
        let dictionary = woyo::Mdx::parse(std::fs::read(root.join("duplicates.mdx"))?, "duplicates")?;
        let prefix: Vec<String> = dictionary.prefix("a",2)?.into_iter().map(str::to_owned).collect();
        let fuzzy: Vec<String> = dictionary.fuzzy("a",1,2)?.into_iter().map(str::to_owned).collect();
        let broken = woyo::Mdx::parse(std::fs::read(root.join("dangling.mdx"))?,"dangling")?;
        let dangling = broken.lookup("x").unwrap_err().to_string();
        let cycle = broken.lookup("y").unwrap_err().to_string();
        let mut chain = woyo::link::Chain { load: |path:&str| Err(woyo::Error::KeyNotFound(path.to_owned())), limit:10 };
        let direct = chain.text("@@@LINK=missing").unwrap_err().to_string();
        let old = vec![woyo::types::Entry {headword:"old".into(),record_offset:0}];
        let new = vec![woyo::types::Entry {headword:"new".into(),record_offset:0}];
        let cache = woyo::index::Cache::new(root.join("stale.idx"),&old,woyo::Limits::default());
        cache.save(&woyo::Index::build(&old,woyo::Limits::default())?)?;
        let current = woyo::index::Cache::new(root.join("stale.idx"),&new,woyo::Limits::default());
        let loaded = current.open()?;
        let stale = json!({"old":loaded.exact("old"),"new":loaded.exact("new")});
        use std::io::Write;
        use woyo::Decode;
        let payload = vec![b'A';1024*1024];
        let mut encoder = flate2::write::ZlibEncoder::new(Vec::new(),flate2::Compression::default());
        encoder.write_all(&payload)?;
        let compressed = encoder.finish()?;
        let mut block = 0x02000000_u32.to_be_bytes().to_vec();
        block.extend_from_slice(&adler::adler32_slice(&payload).to_be_bytes());
        block.extend_from_slice(&compressed);
        let decoded = woyo::decompress::Block {size:1,limit:1}.decode(&block).unwrap_err().to_string();
        Ok(json!({"prefix_a_limit2":prefix,"fuzzy_a_limit2":fuzzy,"dangling_lookup":dangling,"cycle_lookup":cycle,"direct_chain_dangling":direct,"same_stamp_cache":stale,"declared_block_size":1,"oversized_zlib_error":decoded,"public_fields":"private; compile probe recorded separately"}))
    }
}

fn main() {
    let arguments:Vec<String> = std::env::args().collect();
    let result = if arguments.get(1).map(String::as_str) == Some("audit") {
        Audit::run(Path::new(&arguments[2]))
    } else if arguments.get(2).map(String::as_str) == Some("resources") {
        Bench::resources(&arguments[1],Path::new(&arguments[3]))
    } else {
        Bench::run(&arguments[1],&arguments[2],Path::new(&arguments[3]))
    };
    match result {
        Ok(value) => println!("{value}"),
        Err(error) => {
            println!("{}",json!({"error":error.to_string(),"arguments":arguments}));
            std::process::exit(1);
        }
    }
}

